#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> v(n);
    for (int &x : v)
        cin >> x;

    if (n <= 1) {
        cout << 0 << '\n';
        return 0;
    }

    int mc = 1, current = 1;
    for (int i = 1; i < n; ++i) {
        if (v[i] == v[i - 1] + 1)
            ++current;
        else
            current = 1;
        mc = max(mc, current);
    }

    vector<int> r;
    for (int i = 0; i + mc <= n; ++i) {
        bool valid = true;
        for (int j = i + 1; j < i + mc; ++j) {
            if (v[j] != v[j - 1] + 1) {
                valid = false;
                break;
            }
        }

        if (valid) {
            r.assign(v.begin() + i, v.begin() + i + mc);
            if (r.front() == 1)
                break;
        }
    }

    int answer = static_cast<int>(r.size()) - 2;
    if (!r.empty() && (r.front() == 1 || r.back() == 1000))
        ++answer;

    cout << max(answer, 0) << '\n';
    return 0;
}

